import type { WixDataBulkSaveOptions } from './types'

/**
 * Options builder for bulk save operations.
 *
 * Use this builder to configure bulk save behavior such as hooks suppression and reference saving.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataBulkSaveOptionsBuilder {
  /**
   * Sets whether to suppress hooks.
   *
   * When `true`, the bulk save runs without triggering hooks.
   */
  withSuppressHooks(value: boolean): WixDataBulkSaveOptionsBuilder
  /**
   * Sets whether to include draft items when saving items in bulk.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataBulkSaveOptionsBuilder
  /**
   * Sets whether to save referenced items when saving items in bulk.
   */
  withSaveReferences(value: boolean): WixDataBulkSaveOptionsBuilder
  /**
   * Builds the bulk save options object.
   */
  build(): WixDataBulkSaveOptions
}

class WixDataBulkSaveOptionsBuilderImpl
  implements WixDataBulkSaveOptionsBuilder
{
  constructor(private readonly options: WixDataBulkSaveOptions = {}) {}

  withSuppressHooks(value: boolean): WixDataBulkSaveOptionsBuilder {
    return this.copy({ suppressHooks: value })
  }

  withShowDrafts(value: boolean): WixDataBulkSaveOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  withSaveReferences(value: boolean): WixDataBulkSaveOptionsBuilder {
    return this.copy({ saveReferences: value })
  }

  build(): WixDataBulkSaveOptions {
    return {
      ...this.options,
    }
  }

  private copy(options: WixDataBulkSaveOptions): WixDataBulkSaveOptionsBuilder {
    return new WixDataBulkSaveOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new bulk save options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create a bulk save options builder"
 * import { items, BulkSaveOptionsBuilder } from '@wix/data'
 *
 * const options = BulkSaveOptionsBuilder()
 *   .withSuppressHooks(true)
 *   .withSaveReferences(true)
 *   .build()
 *
 * const result = await items.bulkSave('myCollection', [{ _id: 'foo', references: ['ref1', 'ref2'] }], options)
 * ```
 */
export const BulkSaveOptionsBuilder: () => WixDataBulkSaveOptionsBuilder = () =>
  new WixDataBulkSaveOptionsBuilderImpl()
